com.mirth.connect.plugins.javascriptstep.script:
//Get DB information
var jdbdcDriver = configurationMap.get("jdbdcDriver");
var jbdcUrl = configurationMap.get("jbdcUrl");
var dbName = configurationMap.get("dbName");
var dbPassword = configurationMap.get("dbPassword");
var emptyRecord = channelMap.get("noRecords");
var username = configurationMap.get("sftpUserName");
var password = configurationMap.get("sftpPassword");
var ip = configurationMap.get("sftpIp");
var port = configurationMap.get("sftpPort");
var screeningPath = configurationMap.get("screeningLocation");
var screeningLocation = JSON.parse(screeningPath);
var mcoCode = globalChannelMap.get("mcoCode");
var errorCodeString = configurationMap.get("screeningErrorCodes")
var errorCodes = JSON.parse(errorCodeString);
var errorTypeMap = globalChannelMap.get("errorTypeMap");
logger.info("erroMap" + errorTypeMap)
var errorsToAppend = [];
var fileNames = [];
var originalFileName = msg.toString();
logger.info(originalFileName)
channelMap.put("controlFileName", originalFileName)
var controlFileHeader = String(configurationMap.get("controlFileHeader"));
var patientFileHeader = String(configurationMap.get("patientFileHeader"));
var screeningFileHeader = String(configurationMap.get("screnningFileHeader"));
var screeningResponseFileHeader = String(configurationMap.get("screeningResponseFileHeader"));
var consentFileHeader = String(configurationMap.get("consentFileHeader"));
var referralFileHeader = String(configurationMap.get("referralFileHeader"));
var assessmentFileHeader = String(configurationMap.get("assessmentFileHeader"));
logger.info("assementHeader" + assessmentFileHeader)
var splittedFileName = originalFileName.split("_");
var mcoCode = splittedFileName[0].toUpperCase();
globalChannelMap.put("mcoCode", mcoCode);
var dbConn;
var File = Packages.java.io.File;
var FileInputStream = Packages.java.io.FileInputStream;
var FileOutputStream = Packages.java.io.FileOutputStream;
var BufferedReader = Packages.java.io.BufferedReader;
var InputStreamReader = Packages.java.io.InputStreamReader;
var FileReader = Packages.java.io.FileReader;
var fileNameScreeningDetailIdMap = sourceMap.get("fileNameScreeningDetailIdMap");

logger.info(mcoCode)


logger.info(screeningLocation)
try {

    //  Initialize validation flag and error messages array
    var validated = true;
    var header = controlFileHeader.split("|").map(function (h) {
        return h.trim().toUpperCase();
    });
    logger.info(header)
    // logger.info(patienFileHeader)
       var patientHeader = patientFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })
       var screnningHeader = screeningFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })

       var screeningResponseHeader = screeningResponseFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })

       var consentHeader = consentFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })
       var referralHeader = referralFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })

       var assessmentHeader = assessmentFileHeader.split("|").map(function (h) {
           return h.trim().toUpperCase();
       })

    //  Define the key-value pairs for files and their expected headers
    var fileHeaders = {
        "patient": patientFileHeader,
        "consent": consentFileHeader,
        "screening": screeningFileHeader,
        "screeningresponse": screeningResponseFileHeader,
        "referral": referralFileHeader,
        "assessment": assessmentFileHeader,
        "control": controlFileHeader
    };

    //  Define the list of files to process (file names must match the keys in the fileHeaders map)
    try {
        dbConn = DatabaseConnectionFactory.createDatabaseConnection(
            jdbdcDriver,
            jbdcUrl,
            dbName,
            dbPassword
        );
        logger.info(originalFileName)

        var fileNameResult = dbConn.executeCachedQuery(
            "select mco_screening_id FROM screening_extracts.mco_screening_extracts where control_file_name = ? and is_active = '1'",
            [originalFileName]
        );
        mco_screening_id = fileNameResult.next()
            ? fileNameResult.getInt("mco_screening_id")
            : null;
        logger.info(mco_screening_id)
        channelMap.put("screeningId", mco_screening_id)

        //        // var fileNameResult = dbConn.executeCachedQuery(
        //        //     "select mco_screening_id FROM screening_extracts.mco_screening_extracts where control_file_name = ? and is_active = '1'",
        //        //     [originalFileName]
        //        // );
        //        // mco_screening_id = fileNameResult.next()
        //        //     ? fileNameResult.getInt("mco_screening_id")
        //        //     : null;
        // logger.info(mco_screening_id)
        // channelMap.put("screeningId", mco_screening_id)
        // var fileResult = dbConn.executeCachedQuery(
        //     "SELECT file_name FROM screening_extracts.mco_screening_extracts_details WHERE mco_screening_id = ? AND LOWER(file_name) NOT LIKE '%_control_%' and is_active='1' and record_count >0",
        //     // "SELECT file_name FROM screening_extracts.mco_screening_extracts_details WHERE mco_screening_id = ?  and is_active='1' and record_count >0",
        //     [mco_screening_id]
        // );
        // logger.info(fileResult)

        // while (fileResult.next()) {
        //     logger.info(fileResult.getString("file_name"));
        //     fileNames.push(fileResult.getString("file_name"));
        // }
        fileNames = sourceMap.get("fileInformation")
        var screeningDetailsId = fileNameScreeningDetailIdMap[originalFileName]
        channelMap.put("screeningDetailsId", screeningDetailsId);
        logger.info("got file information" + fileNames)

    }
    catch (err) {
        logger.info(err);
        throw {
            errorType: "POSTGRES ERROR",
            description: "Unable to connect to db",
            rawError: err,
            stackTrace: err.stack,
            msg: err.message
        };
    }

    // Initialize the global validated flag
    var allFilesValid = true;
    // This will track whether all files pass validation
    logger.info("all files valid before validation"+allFilesValid)

    // Establish the SFTP connection
    try {


        // Loop through each file to fetch and validate
        for (var fileIndex = 0; fileIndex < fileNames.length; fileIndex++) {
            var filename = fileNames[fileIndex]['fileName'];
            logger.info("fileName" + filename)
            var fi = fileNames[fileIndex];
            if (fi.skipFile) continue;
            //            var skipFile=fileNames[fileIndex]['skipfile'];
            //            if (skipFile){
            //            continue;
            //            }

            // Determine the file type from the file name (you can extract the key from the file name)
            var fileType = filename.split('_')[1];
            logger.info(fileType)
            var path = screeningLocation[mcoCode]["temp"]
            var filePath = path + "/" + filename;
            // var inputStream = sftpChannel.get(filePath);
            // var fileContent = new java.io.InputStreamReader(inputStream);
            // var bufferedReader = new java.io.BufferedReader(fileContent);
            var file = File(filePath)
            var reader = new FileReader(file)
            var readBuffer = BufferedReader(reader)

            // Read the content of the file into a variable
            //var fileContent = "";
            var headerLine = "";
            var fileLineCounter = 0;
            var oneRecordFound = false;
            var line;
            while ((line = readBuffer.readLine()) != null) {
                logger.info(line.toString())
                if (fileLineCounter == 0) {
                    headerLine = line;
                }
                else {
                    logger.info("inside line" + line.toString().trim())
                    logger.info("inside line length" + line.toString().trim().length())
                    if (line.toString().trim().length() > 0) {
                        oneRecordFound = true;
                        logger.info("inside one record found")
                        readBuffer.close();
                        break;
                    }
                    else {
                        logger.info("inside else")
                    }
                }
                fileLineCounter++;
            }

            //If not a single valid record is found, the buffer will still be open, so we should close it manually

            // Close the SFTP connection
            if (oneRecordFound == false) {
                readBuffer.close();
            }


            //            //  Split the file into lines and validate
            //            var lines = fileContent.split("\n").map(function (line) {
            //                logger.info(line)
            //                return line.trim();
            //            }).filter(function (line) {
            //                return line.length > 0;  // Remove any empty lines
            //            });
            //
            //            // Validate if the file is empty
            //            logger.info("144" + lines)

            // Get the expected header for this file type
            var expectedHeader = fileHeaders[fileType.toLowerCase()];
            var header = expectedHeader

            // Validate the header of the file
            //            var actualHeader = String(headerLine).split('|');
            var actualHeader = String(headerLine);
            var invalidDelimiterRegex = /[,\t; ]/;
            function isValidHeaderField(value) {
                return !invalidDelimiterRegex.test(value);
            }
            function arraysEqual(a1, a2) {
                logger.info("a1" + a1)
                logger.info("a2" + a2)
                if (a1.length !== a2.length) {
                    logger.info("Header length mismatch. Expected: " + a1.length + ", Actual: " + a2.length);
                    return false;
                }
                if (a2.length <= 1) return false;
                for (var i = 0; i < a1.length; i++) {
                    var val1 = a1[i].trim().toLowerCase();
                    var val2 = a2[i].trim().toLowerCase();

                    // Reject if any field contains a invalid delimeter— indicating mixed delimiters
                    if (!isValidHeaderField(val1) || !isValidHeaderField(val2)) {
                        logger.info("Invalid character in header field: " + a2[i]);
                        return false;
                    }

                    if (val1 !== val2) {
                        return false;
                    }
                }
                return true;
            }

            function headerEquals(expected, actual) {

                // // Remove BOM
                // expected = expected.replace(/^\uFEFF/, '');
                // actual = actual.replace(/^\uFEFF/, '');

                // // Remove carriage returns
                // expected = expected.replace(/\r/g, '');
                // actual = actual.replace(/\r/g, '');

                // // Remove zero-width and bidi characters
                // expected = expected.replace(/[\u200B-\u200F\u202A-\u202E]/g, '');
                // actual = actual.replace(/[\u200B-\u200F\u202A-\u202E]/g, '');

                // // Normalize NBSP and other unicode spaces
                // expected = expected.replace(/\u00A0/g, ' ');
                // actual = actual.replace(/\u00A0/g, ' ');

                // Trim outer whitespace
                logger.info("Expected: [" + expected + "]");
                logger.info("Actual:   [" + actual + "]");
                expected = expected.trim();
                actual = actual.trim();

                // // Collapse multiple spaces
                // expected = expected.replace(/\s+/g, ' ');
                // actual = actual.replace(/\s+/g, ' ');



                logger.info(expected.toLowerCase() == actual.toLowerCase())

                return expected.toLowerCase() == actual.toLowerCase();
            }



            logger.info("after length");

            if (!headerEquals(header, actualHeader)) {
                logger.info("inside invalid header")
                errorsToAppend.push({
                    code: errorCodes["EC003"]["code"],
                    description: errorCodes["EC003"]["description"],
                    fileName: filename,
                    status: "ERROR"

                });
                allFilesValid = false;
                continue;
            }
            logger.info("all files valid after header validation"+allFilesValid)
            if (oneRecordFound == false) {
                logger.info("inside one record found")
                errorsToAppend.push({
                    code: errorCodes["EC004"]["code"],
                    description: errorCodes["EC004"]["description"],
                    fileName: filename,
                    status: "ERROR"

                });
                allFilesValid = false;
                continue;
            }
            logger.info("all files valid after one record found" + allFilesValid)

            //  If any validation failed, mark the file as invalid
            if (!allFilesValid) {
                logger.info("inside file invalid case")
                // try {
                //     if (!dbConn) {
                //         dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                //             jdbdcDriver,
                //             jbdcUrl,
                //             dbName,
                //             dbPassword
                //         );
                //     }
                //     var fileResult = dbConn.executeCachedQuery(
                //         "UPDATE screening_extracts.mco_screening_extracts_details SET status ='ERROR' WHERE file_name=?  returning *",
                //         [filename]
                //     );
                //     logger.info("logged success fully in db")

                // }
                // catch (err) {
                //     throw {
                //         errorType: "POSTGRES ERROR",
                //         description: "Unable to connect to db",
                //         rawError: err,
                //         stackTrace: err.stack,
                //         msg: err.message
                //     };
                // }
                logger.error("File validation failed for: " + filename);
            } else {
                logger.info("File " + filename + " has been validated successfully.");

                // try {
                //     if (!dbConn) {
                //         dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                //             jdbdcDriver,
                //             jbdcUrl,
                //             dbName,
                //             dbPassword
                //         );

                //     }
                //     var fileResult = dbConn.executeCachedQuery(
                //         "UPDATE screening_extracts.mco_screening_extracts_details SET status ='VALIDATED' WHERE file_name=?  returning *",
                //         [filename]
                //     );

                // }
                // catch (err) {
                //     throw {
                //         errorType: "POSTGRES ERROR",
                //         description: "Unable to connect to db",
                //         rawError: err,
                //         stackTrace: err.stack,
                //         msg: err.message
                //     };
                // }
            }
        }
    }
    catch (err) {
        logger.info(err)
        throw {
            errorType: "SFTP",
            description: "Unable to copy or move file",
            rawError: err,
            stackTrace: err.stack,
            msg: err.message
        }
    }

    logger.info("all files valid" + allFilesValid)

    //  After processing all files, set global validated flag
    if (allFilesValid) {
        try {
            if (!dbConn) {
                dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                    jdbdcDriver,
                    jbdcUrl,
                    dbName,
                    dbPassword
                );

            }
            for (var file = 0; file < fileNames.length; file++) {
                var fname = fileNames[file]['fileName']
                var fileResults = dbConn.executeCachedQuery(
                    "UPDATE screening_extracts.mco_screening_extracts_details SET status ='VALIDATED',updated_on_utc=NOW() WHERE file_name=? and is_active ='1' returning *",
                    [fname]
                );
            }
            var fileResult = dbConn.executeCachedQuery(
                "UPDATE screening_extracts.mco_screening_extracts SET status ='VALIDATED',updated_on_utc=NOW() WHERE control_file_name=? and is_active ='1'  returning *",
                [originalFileName]
            );
            logger.info("All files have been successfully validated.");
        }
        catch (err) {
            throw {
                errorType: "POSTGRES ERROR",
                description: "Unable to connect to db",
                rawError: err,
                stackTrace: err.stack,
                msg: err.message
            };
        }

        channelMap.put("sentToMco", allFilesValid)
    } else {
        try {
            if (!dbConn) {
                dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                    jdbdcDriver,
                    jbdcUrl,
                    dbName,
                    dbPassword
                );

            }
            for (var file = 0; file < fileNames.length; file++) {
                var fname = fileNames[file]['fileName']
                var fileResults = dbConn.executeCachedQuery(
                    "UPDATE screening_extracts.mco_screening_extracts_details SET status ='ERROR',updated_on_utc =NOW() WHERE file_name=? and is_active ='1' returning *",
                    [fname]
                );
            }
            var fileResult = dbConn.executeCachedQuery(
                "UPDATE screening_extracts.mco_screening_extracts SET status ='ERROR',updated_on_utc=NOW() WHERE control_file_name=? and is_active ='1' returning *",
                [originalFileName]
            );
            logger.info("All files have been successfully validated.");
        }
        catch (err) {
            throw {
                errorType: "POSTGRES ERROR",
                description: "Unable to connect to db",
                rawError: err,
                stackTrace: err.stack,
                msg: err.message
            };
        }

        channelMap.put("sentToMco", allFilesValid)
    }


    // Set the global validated status in globalChannelMap
    globalChannelMap.put("validated", allFilesValid);
    globalChannelMap.put("error", errorsToAppend);
    globalChannelMap.put("fileNames", fileNames);

    // Disconnect from SFTP after all files have been processed

}
catch (err) {
    logger.info("error in inserting db" + err)
    try {
        if (!dbConn) {
            dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                jdbdcDriver,
                jbdcUrl,
                dbName,
                dbPassword
            );
        }
        var error_type_id = errorTypeMap["MIRTH_INTERNAL_ERROR"]
        var screening_id = channelMap.get("screeningId");
        var fallbackErrJson = {
            errorType: err.errorType ? err.errorType : "SFTP ERROR",
            description: "Error While copy or moving" + file + "to" + path,
            stack: err.stack,
            msg: err.msg ? err.msg : err.message,
            rawError: err.rawError ? err.rawError : "SFTP ERROR",
        };
        var fileResult = dbConn.executeCachedQuery(
            "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id,mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?,?,?::json, NOW(),NOW(),'1',?) returning *",
            [screening_id,
                screeningDetailsId,
                JSON.stringify(fallbackErrJson),
                error_type_id]

        );

    }
    catch (err) {
        throw {
            errorType: "POSTGRES ERROR",
            description: "Unable to connect to db",
            rawError: err,
            stackTrace: err.stack,
            msg: err.message
        };
    }
    logger.info(err)
    throw err;
} finally {
    if (dbConn) {
        dbConn.close();
    }
}

properties.script:
try {
	var jdbdcDriver = configurationMap.get("jdbdcDriver");
	var jbdcUrl = configurationMap.get("jbdcUrl");
	var dbName = configurationMap.get("dbName");
	var dbPassword = configurationMap.get("dbPassword");
	var screeningPath = configurationMap.get("screeningLocation");
	var screeningLocation = JSON.parse(screeningPath);
	var mcoCode = globalChannelMap.get("mcoCode");
	logger.info("mco code: " + mcoCode);

	var outputFolder = screeningLocation[mcoCode]["dailyFiles"];
	var tempFolder = screeningLocation[mcoCode]["temp"];
	var backupFolder = screeningLocation[mcoCode]["processFiles"];
	var expectedFiles = globalChannelMap.get("fileNames"); // This should be an array
	var errorTypeMap = globalChannelMap.get("errorTypeMap");
	var screeningId = channelMap.get("screeningId");

	var username = configurationMap.get("sftpUserName");
	var password = configurationMap.get("sftpPassword");
	var ip = configurationMap.get("sftpIp");
	var port = configurationMap.get("sftpPort");
	var dbConn;

	var isSuccess = false;

	// Import Java classes

	var File = java.io.File;
	var FileInputStream = java.io.FileInputStream;
	var FileOutputStream = java.io.FileOutputStream;
	var ZipOutputStream = java.util.zip.ZipOutputStream;
	var ZipEntry = java.util.zip.ZipEntry;
	var SimpleDateFormat = java.text.SimpleDateFormat;
	var Date = java.util.Date;
	var Files = java.nio.file.Files;
	var Paths = java.nio.file.Paths;
	var StandardCopyOption = java.nio.file.StandardCopyOption;
	var ArrayList = java.util.ArrayList;
	var HashMap = java.util.HashMap;

	var directory = new File(tempFolder);
	var files = directory.listFiles();
	var availableFilesMap = new java.util.HashMap();
	if (files != null) {
		for (var i = 0; i < files.length; i++) {
			if (files[i].isFile()) {
				var fname = files[i].getName().trim();
				var size = files[i].length();
				if (size > 0) {
					availableFilesMap.put(fname, files[i].getAbsolutePath());
				} else {
					logger.warn("Skipping empty file: " + fname);
				}
			}
		}
	} else {
		logger.error("Directory does not exist or cannot be read: " + tempFolder);
		return;
	}

	// --- Check and Collect Files ---
	var filesToZip = [];
	var allExist = true;
	logger.info("expected files" + expectedFiles)
	for (var fname = 0; fname < expectedFiles.length; fname++) {
		logger.info("logging fname" + expectedFiles[fname]['fileName'])
		var requestedFile = expectedFiles[fname]['fileName'].toString().trim();
		var actualFile = availableFilesMap.get(requestedFile);
		var skipfile=expectedFiles[fname]['skipFile']
		if(skipfile){
			continue;
			}

		if (actualFile == null) {
			logger.warn("Missing or empty file in source: " + requestedFile);
			allExist = false;
		} else {
			filesToZip.push(actualFile); // use actualFile from SFTP list
		}
	}

	if (!allExist) {
		logger.warn("Not all expected files found. Skipping zip.");
		return;
	}

	// --- ZIP Files ---
	var splittedFileName = $('controlFileName').split("_");
	var parts = String(splittedFileName[2]).split(".");
	var dateFormat = parts[0];
	var sdf = new java.text.SimpleDateFormat("yyyyMMdd");
	var todayStr = sdf.format(new java.util.Date());
	var date = dateFormat ? dateFormat : todayStr;
	var zipFileName = mcoCode + "_hrsnob_screenings_" + date + ".zip";
	var zipFilePath = outputFolder + "/" + zipFileName;
	var backupZipPath = backupFolder + "/" + zipFileName;

	var fos = new FileOutputStream(zipFilePath);
	var zos = new ZipOutputStream(fos);

for each (var fullPath in filesToZip) {
	var fileToZip = new File(fullPath);
	var fis = new FileInputStream(fileToZip);
	var entry = new ZipEntry(fileToZip.getName());
	zos.putNextEntry(entry);

	var buffer = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
	var len;
	while ((len = fis.read(buffer)) > 0) {
		zos.write(buffer, 0, len);
	}
	fis.close();
	zos.closeEntry();
}
	zos.close();
	fos.close();
	logger.info("ZIP created successfully: " + zipFilePath);
	logger.info(backupZipPath)
	Files.copy(
		Paths.get(zipFilePath),
		Paths.get(backupZipPath),
		StandardCopyOption.REPLACE_EXISTING
	);
	logger.info("ZIP copied to backup location: " + backupZipPath);
	isSuccess = true;
	channelMap.put("success", isSuccess);

	// --- Clean up temp files from SFTP ---
	for each (var filePath in filesToZip) {
    var fileToDelete = new File(filePath);

    if (fileToDelete.exists() && fileToDelete.isFile()) {
        org.apache.commons.io.FileUtils.deleteQuietly(fileToDelete);
    } else if (fileToDelete.exists() && fileToDelete.isDirectory()) {
        logger.warn("Skipping deletion, found directory: " + fileToDelete.getAbsolutePath());
    } else {
        logger.warn("File not found for deletion: " + fileToDelete.getAbsolutePath());
    }
}
	if (isSuccess) {
		logger.info("logging completed status in db" + isSuccess )
		var controlFileName = channelMap.get('controlFileName');
		var file;
		try {
			if (!dbConn) {
				dbConn = DatabaseConnectionFactory.createDatabaseConnection(
					jdbdcDriver,
					jbdcUrl,
					dbName,
					dbPassword
				);
			}
				for (var j = 0; j < expectedFiles.length; j++) {
					var file=expectedFiles[j]['fileName']
				var fileResult = dbConn.executeCachedQuery(
					"UPDATE screening_extracts.mco_screening_extracts_details SET status ='COMPLETED', updated_on_utc = NOW() WHERE file_name=? and is_active ='1'  returning *",
					[file]
				);
			}
			file = dbConn.executeCachedQuery(
		        "UPDATE screening_extracts.mco_screening_extracts SET status ='COMPLETED', sent_file_name = ?, updated_on_utc = NOW(), sent_to_mco = NOW() WHERE control_file_name = ? AND is_active = '1' RETURNING *",
		        [ zipFileName.toString(), $('controlFileName') ]
		    );
		}
		catch (err) {
			throw {
				errorType: "POSTGRES ERROR",
				description: "Unable to connect to db",
				rawError: err,
				stackTrace: err.stack,
				msg: err.message
			};
		}
	}
} catch (err) {
	logger.error("Error during zip and clean process: " + err);

	try {
		dbConn = DatabaseConnectionFactory.createDatabaseConnection(
			jdbdcDriver,
			jbdcUrl,
			dbName,
			dbPassword
		);
		var error_type_id = errorTypeMap["MIRTH_INTERNAL_ERROR"];
		var fallbackErrJson = {
			errorType: err.errorType ? err.errorType : "MIRTH INTERNAL ERROR",
			description: "Error While copy or moving" + file,
			stack: err.stack,
			msg: err.msg ? err.msg : err.message,
			rawError: err.rawError ? err.rawError : "SFTP ERROR",
		};
		 var mco_screening_details_id = channelMap.get("screeningDetailsId");

		dbConn.executeCachedQuery(
			"INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id,mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?::json, NOW(),NOW(),'1',?) returning *",
			[screeningId,mco_screening_details_id,JSON.stringify(fallbackErrJson), error_type_id]
		);
	} catch (logErr) {
		logger.error("Failed to log error to DB: " + logErr);
	}
	throw {
		errorType: "POSTGRES ERROR",
		description: "Unable to connect to db",
		rawError: err,
		stackTrace: err.stack,
		msg: err.message
	};
} finally {

	if (dbConn) dbConn.close();
}

com.mirth.connect.plugins.javascriptstep.script:
try {
    var errors = $('error')
    var errorFileHeader = configurationMap.get("errorFileHeader");
    var screeningPath = configurationMap.get("screeningLocation");
    var screeningLocation = JSON.parse(screeningPath);
    var mco_code = $('mcoCode');
    var dbConn;
    var jdbdcDriver = configurationMap.get("jdbdcDriver");
    var jbdcUrl = configurationMap.get("jbdcUrl");
    var dbName = configurationMap.get("dbName");
    var dbPassword = configurationMap.get("dbPassword");
    var errorTypeMap = globalChannelMap.get("errorTypeMap");
    logger.info("erroMap" + errorTypeMap)
    var sdf = new java.text.SimpleDateFormat("yyyyMMdd");
    var todayStr = sdf.format(new java.util.Date());
    var splittedFileName = $('controlFileName').split("_")
    var part = String(splittedFileName[2]).split(".");
    var dateString = part[0] ? part[0] : todayStr;
    var fileNameScreeningDetailIdMap = sourceMap.get("fileNameScreeningDetailIdMap");


    // File name to upload
    if (typeof errors === 'string') {
        errors = JSON.parse(errors); // ensure array
    }

    // Build file content
    var output = errorFileHeader + "\n";
    logger.info("error file header" + output);
    var sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    var errorTime = sdf.format(new java.util.Date());
    logger.info("error length"+errors.length)
    for (var i = 0; i < errors.length; i++) {
        var err = errors[i];
        var controlFileName = $('controlFileName');
        var fileName = err.fileName || "UNKNOWN";
        var status = err.status || "ERROR";
        var description = err.description || "UNKNOWN";
        var deliveredDateTime = errorTime;

        output += controlFileName + "|" + fileName + "|" + status + "|" + description + "|" + deliveredDateTime + "\n";
        logger.info("error content" + output)
        try {
            if (!dbConn) {
                dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                    jdbdcDriver,
                    jbdcUrl,
                    dbName,
                    dbPassword
                );
            }
           logger.info("db connection established")
            var error_type_id = errorTypeMap["VALIDATION_ERROR"]
            var screening_id = $('screeningId');
            var fallbackErrJson = {
                fileName: err.fileName || "UNKNOWN",
                controlFileName: $('controlFileName'),
                err: err.description

            };
            var screeningDetailsId= fileNameScreeningDetailIdMap[err.fileName];
            logger.info(screeningDetailsId)
         var fileResult = dbConn.executeCachedQuery(
                "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id,mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?,?,?::json, NOW(),NOW(),'1',?) returning *",
                [screening_id,
                screeningDetailsId,
                    JSON.stringify(fallbackErrJson),
                    error_type_id]

            );
            logger.info("db query completed")

        }
        catch (err) {
            throw {
                errorType: "POSTGRES ERROR",
                description: "Unable to connect to db",
                rawError: err,
                stackTrace: err.stack,
                msg: err.message
            };
        }

        logger.info("error file content" + output);

    } 
    var remoteFileName = $('mcoCode') + "_Error_" + dateString + ".txt";
    var backupRemotePath = screeningLocation[mco_code]["errorFiles"];

    channelMap.put("errorContent", output)
    channelMap.put("errorFileName", remoteFileName)
    channelMap.put("errorFilePath", backupRemotePath)
}
catch (err) {
    try {
        if (!dbConn) {
            dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                jdbdcDriver,
                jbdcUrl,
                dbName,
                dbPassword
            );
        }
        var error_type_id = errorTypeMap["MIRTH_INTERNAL_ERROR"]
        var screening_id = $('screeningId');
        var mco_screening_details_id = channelMap.get("screeningDetailsId");
        var fallbackErrJson = {
            errorType: err.errorType ? err.errorType : "MIRTH INTERNAL ERROR",
            description: "Error While copy or moving" + file + "to" + path,
            stack: err.stack,
            msg: err.msg ? err.msg : err.message,
            rawError: err.rawError ? err.rawError : "SFTP ERROR",
        };
        var fileResult = dbConn.executeCachedQuery(
            "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id, mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?,?::json, NOW(),NOW(),'1',?) returning *",
            [screening_id,
            mco_screening_details_id,
                JSON.stringify(fallbackErrJson),
                error_type_id]

        );

    }
    catch (err) {
        throw {
            errorType: "POSTGRES ERROR",
            description: "Unable to connect to db",
            rawError: err,
            stackTrace: err.stack,
            msg: err.message
        };
    }
    logger.info(err)
    throw err;
} finally {
    if (dbConn) {
        dbConn.close();
    }
}

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
var errorTypeMap = {};
var mcoMap={}





try {
	var dbConn = DatabaseConnectionFactory.createDatabaseConnection(configurationMap.get('jdbdcDriver'), configurationMap.get('jbdcUrl'), configurationMap.get('dbName'), configurationMap.get('dbPassword'));
    var rsErr = dbConn.executeCachedQuery(
        "SELECT screening_error_type_name, screening_error_type_id FROM screening_extracts.screening_error_types WHERE is_active = '1'"
    );
    while (rsErr.next()) {
        errorTypeMap[rsErr.getString("screening_error_type_name")] = rsErr.getLong("screening_error_type_id");

    }
    globalChannelMap.put("errorTypeMap", errorTypeMap);
    var rsRes = dbConn.executeCachedQuery(
        "SELECT resource_type_id FROM screening_extracts.resource_types WHERE UPPER(resource_type_name) = 'BUNDLE' AND is_active = '1'"
    );
    if (rsRes.next()) {
        globalChannelMap.put("bundleResourceTypeId", rsRes.getLong("resource_type_id"));
    }
    var rtRes = dbConn.executeCachedQuery(
        "SELECT resource_type_id FROM screening_extracts.resource_types WHERE UPPER(resource_type_name) = 'FLATFILE' AND is_active = '1'"
    );
     if (rtRes.next()) {
        globalChannelMap.put("flatFileResourceId", rtRes.getLong("resource_type_id"));
    }
    var rsMco = dbConn.executeCachedQuery(
        "SELECT tenant_id, tenant_name,tenant_short_code FROM techbd_udi_ingress.tenants WHERE is_active = '1'"
    );

    while (rsMco.next()) {
        mcoMap[rsMco.getString("tenant_short_code")] = rsMco.getString("tenant_id");    
    }

    globalChannelMap.put("mcoMap", mcoMap);

} catch (e) {
    logger.error("Error initializing globalChannelMap values in Deliver files to MCO: " + e);
} finally {
    if (dbConn) dbConn.close();
}

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
